// smoke.spec.js — Create ZIP File Online: real drops, real downloads, archive contents checked byte by byte.
// Fixtures: tests/fixtures/solar-oven-report/ (fictional school project, generated by tests/tools/make-fixtures.js).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const FIX = path.join(__dirname, 'fixtures', 'solar-oven-report');
const fixture = (rel) => path.join(FIX, rel);
const THREE = [
  { rel: 'outline.txt', type: 'text/plain' },
  { rel: 'temperatures.csv', type: 'text/csv' },
  { rel: 'chart.png', type: 'image/png' },
];
const payload = (list) => list.map(({ rel, type, name }) => ({ name: name || path.basename(rel), type, b64: fs.readFileSync(fixture(rel)).toString('base64') }));

// Minimal ZIP reader (central directory) so the tests need nothing but Node.
function readZip(buf) {
  let eocd = -1;
  for (let i = buf.length - 22; i >= 0; i--) if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  if (eocd < 0) throw new Error('no end of central directory');
  const count = buf.readUInt16LE(eocd + 10);
  let p = buf.readUInt32LE(eocd + 16);
  const entries = [];
  for (let n = 0; n < count; n++) {
    expect(buf.readUInt32LE(p)).toBe(0x02014b50);
    const flags = buf.readUInt16LE(p + 8);
    const method = buf.readUInt16LE(p + 10);
    const csize = buf.readUInt32LE(p + 20);
    const usize = buf.readUInt32LE(p + 24);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    const offset = buf.readUInt32LE(p + 42);
    const name = buf.slice(p + 46, p + 46 + nameLen).toString('utf8');
    const lh = offset + 30 + buf.readUInt16LE(offset + 26) + buf.readUInt16LE(offset + 28);
    const raw = buf.slice(lh, lh + csize);
    entries.push({ name, flags, method, usize, data: () => (method === 0 ? raw : zlib.inflateRawSync(raw)) });
    p += 46 + nameLen + extraLen + commentLen;
  }
  return entries;
}

async function drop(page, files) {
  await page.evaluate((list) => {
    const dt = new DataTransfer();
    for (const f of list) {
      const bytes = Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0));
      dt.items.add(new File([bytes], f.name, { type: f.type }));
    }
    document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
  }, files);
}

// Simulates a folder drop: fake FileSystemEntry objects, like Chromium/Firefox/Safari hand over for a dropped directory.
async function dropFolder(page, folderName, files) {
  await page.evaluate(({ folderName, list }) => {
    const root = { name: folderName, isFile: false, isDirectory: true, children: [] };
    for (const f of list) {
      const parts = f.rel.split('/');
      let dir = root;
      for (const part of parts.slice(0, -1)) {
        let next = dir.children.find((c) => c.name === part);
        if (!next) { next = { name: part, isFile: false, isDirectory: true, children: [] }; dir.children.push(next); }
        dir = next;
      }
      const bytes = Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0));
      const file = new File([bytes], parts.at(-1), { type: f.type, lastModified: Date.UTC(2026, 3, 14, 12, 0) });
      dir.children.push({ name: parts.at(-1), isFile: true, isDirectory: false, file: (ok) => setTimeout(() => ok(file)) });
    }
    const wire = (d) => {
      d.children.forEach((c) => c.isDirectory && wire(c));
      d.createReader = () => { let done = false; return { readEntries: (ok) => setTimeout(() => { ok(done ? [] : d.children); done = true; }) }; };
    };
    wire(root);
    const ev = new Event('drop', { bubbles: true, cancelable: true });
    Object.defineProperty(ev, 'dataTransfer', { value: { files: [], items: [{ kind: 'file', webkitGetAsEntry: () => root }] } });
    document.getElementById('dropzone').dispatchEvent(ev);
  }, { folderName, list: files.map((f) => ({ ...f, b64: fs.readFileSync(fixture(f.src || f.rel)).toString('base64') })) });
}

async function createAndDownload(page, trigger = () => page.click('#create')) {
  const [download] = await Promise.all([page.waitForEvent('download'), trigger()]);
  const buf = fs.readFileSync(await download.path());
  return { download, buf };
}

const kb = (n) => (n < 10 * 1024 ? `${(n / 1024).toFixed(1)} KB` : `${Math.round(n / 1024)} KB`);
const fmt = (n) => (n < 1024 ? `${n} B` : kb(n));
const sizeOf = (rel) => fs.statSync(fixture(rel)).size;

test.describe('Create ZIP File Online', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
    await expect(page.locator('#create')).toBeDisabled();
    await expect(page.locator('#empty-state')).toBeVisible();
  });

  test('dropping three sample files lists them with their sizes', async ({ page }) => {
    await drop(page, payload(THREE));
    const rows = page.locator('#file-list .zip-item');
    await expect(rows).toHaveCount(3);
    for (const [i, f] of THREE.entries()) {
      await expect(rows.nth(i).locator('.zip-item__name')).toHaveText(f.rel);
      await expect(rows.nth(i).locator('.zip-item__size')).toHaveText(fmt(sizeOf(f.rel)));
      await expect(rows.nth(i).getByRole('button', { name: `Remove ${f.rel}` })).toBeVisible();
    }
    const total = THREE.reduce((s, f) => s + sizeOf(f.rel), 0);
    await expect(page.locator('#total-size')).toHaveText(`${fmt(total)} total`);
    await expect(page.locator('#file-count')).toHaveText('(3)');
    await expect(page.locator('#empty-state')).toBeHidden();
    await expect(page.locator('#create')).toBeEnabled();
  });

  test('pressing Create ZIP downloads an archive named archive.zip larger than 1 KB', async ({ page }) => {
    await drop(page, payload(THREE));
    const { download, buf } = await createAndDownload(page);
    expect(download.suggestedFilename()).toBe('archive.zip');
    expect(buf.length).toBeGreaterThan(1024);
    expect(buf.slice(0, 4).toString('binary')).toBe('PK\x03\x04');
    const entries = readZip(buf);
    expect(entries.map((e) => e.name).sort()).toEqual(['chart.png', 'outline.txt', 'temperatures.csv']);
    for (const e of entries) expect(e.data().equals(fs.readFileSync(fixture(e.name)))).toBe(true);
    // Text is deflated at the default Fast level, the PNG is stored as is.
    expect(entries.find((e) => e.name === 'outline.txt').method).toBe(8);
    expect(entries.find((e) => e.name === 'chart.png').method).toBe(0);
    await expect(page.locator('#download')).toHaveText('Download archive.zip');
    await expect(page.locator('#download')).toHaveAttribute('download', 'archive.zip');
  });

  test('removing one file from the list excludes it from the result', async ({ page }) => {
    await drop(page, payload(THREE));
    await page.getByRole('button', { name: 'Remove temperatures.csv' }).click();
    await expect(page.locator('#file-list .zip-item')).toHaveCount(2);
    await expect(page.locator('#file-list')).not.toContainText('temperatures.csv');
    // Focus stays in the list for keyboard users.
    await expect(page.locator('#file-list .zip-item__remove').nth(1)).toBeFocused();
    const { buf } = await createAndDownload(page);
    const names = readZip(buf).map((e) => e.name).sort();
    expect(names).toEqual(['chart.png', 'outline.txt']);
  });

  test('dropping a folder keeps its relative paths inside the archive', async ({ page }) => {
    await dropFolder(page, 'solar-oven-report', [
      ...THREE,
      { rel: 'notes/build-notes.txt', type: 'text/plain' },
      { rel: '.DS_Store', src: 'outline.txt', type: '' }, // hidden system file: skipped by default
    ]);
    await expect(page.locator('#file-list .zip-item')).toHaveCount(4);
    await expect(page.locator('#file-list')).toContainText('solar-oven-report/notes/');
    const { buf } = await createAndDownload(page);
    const entries = readZip(buf);
    expect(entries.map((e) => e.name).sort()).toEqual([
      'solar-oven-report/chart.png',
      'solar-oven-report/notes/build-notes.txt',
      'solar-oven-report/outline.txt',
      'solar-oven-report/temperatures.csv',
    ]);
    const notes = entries.find((e) => e.name.endsWith('build-notes.txt'));
    expect(notes.data().toString('utf8')).toBe(fs.readFileSync(fixture('notes/build-notes.txt'), 'utf8'));
  });

  test('Choose folder keeps relative paths too', async ({ page }) => {
    await page.setInputFiles('#folder-input', FIX);
    await expect(page.locator('#file-list .zip-item')).toHaveCount(4);
    const { buf } = await createAndDownload(page);
    const names = readZip(buf).map((e) => e.name).sort();
    expect(names).toEqual([
      'solar-oven-report/chart.png',
      'solar-oven-report/notes/build-notes.txt',
      'solar-oven-report/outline.txt',
      'solar-oven-report/temperatures.csv',
    ]);
  });

  test('the result shows the total before and after size', async ({ page }) => {
    await drop(page, payload(THREE));
    const { buf } = await createAndDownload(page);
    const before = THREE.reduce((s, f) => s + sizeOf(f.rel), 0);
    const result = page.locator('#results .zip-result');
    await expect(result).toBeVisible();
    await expect(result.locator('#stat-before')).toHaveText(fmt(before));
    await expect(result.locator('#stat-after')).toHaveText(fmt(buf.length));
    const saved = (Math.floor((1 - buf.length / before) * 1000) / 10).toFixed(1);
    await expect(result.locator('#stat-saved')).toHaveText(`${saved}% smaller`);
    await expect(page.locator('#results .alert--error')).toHaveCount(0);
  });

  test('Enter on the archive name creates the ZIP with that name, skipping hidden files and numbering duplicates', async ({ page }) => {
    await drop(page, payload([...THREE, { rel: 'outline.txt', type: 'text/plain' }, { rel: 'outline.txt', type: 'text/plain', name: '.DS_Store' }, { rel: 'outline.txt', type: 'text/plain', name: 'Café notes.txt' }]));
    await expect(page.locator('#file-list .zip-item')).toHaveCount(5);
    await expect(page.locator('#notices')).toContainText('.DS_Store');
    await page.fill('#archive-name', 'Solar Oven Report');
    await page.selectOption('#level', 'best');
    const { download, buf } = await createAndDownload(page, () => page.press('#archive-name', 'Enter'));
    expect(download.suggestedFilename()).toBe('Solar Oven Report.zip');
    const entries = readZip(buf);
    expect(entries.map((e) => e.name).sort()).toEqual(['Café notes.txt', 'chart.png', 'outline (2).txt', 'outline.txt', 'temperatures.csv']);
    const cafe = entries.find((e) => e.name.startsWith('Caf'));
    expect(cafe.flags & 0x800).toBe(0x800); // UTF-8 name flag
  });

  test('empty files are allowed and the button is disabled again after Clear all', async ({ page }) => {
    await page.evaluate(() => {
      const dt = new DataTransfer();
      dt.items.add(new File([], 'empty.txt', { type: 'text/plain' }));
      document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    });
    await expect(page.locator('#file-list .zip-item__size')).toHaveText('0 B');
    const { buf } = await createAndDownload(page);
    expect(readZip(buf).map((e) => [e.name, e.usize])).toEqual([['empty.txt', 0]]);
    await expect(page.locator('#stat-saved')).toHaveText('n/a (empty files)');
    await page.click('#clear-all');
    await expect(page.locator('#create')).toBeDisabled();
    await expect(page.locator('#results .zip-result')).toHaveCount(0);
  });

  test('a file that cannot be read is skipped with an error notice', async ({ page }) => {
    // Pick a real file from disk, then delete it before zipping (like a USB stick pulled out).
    const tmpDir = path.join(__dirname, '.tmp');
    fs.mkdirSync(tmpDir, { recursive: true });
    const gone = path.join(tmpDir, 'gone.txt');
    fs.writeFileSync(gone, 'this file will disappear before zipping\n');
    try {
      await drop(page, payload(THREE.slice(0, 2)));
      await page.setInputFiles('#file-input', gone);
      await expect(page.locator('#file-list .zip-item')).toHaveCount(3);
      fs.unlinkSync(gone);
      const { buf } = await createAndDownload(page);
      expect(readZip(buf).map((e) => e.name).sort()).toEqual(['outline.txt', 'temperatures.csv']);
      await expect(page.locator('#results .alert.alert--error')).toContainText('gone.txt');
      await expect(page.locator('#results .zip-result')).toBeVisible();
    } finally {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  test('a total over the safe limit shows an error and disables Create ZIP', async ({ page }) => {
    await page.evaluate(() => {
      const dt = new DataTransfer();
      const huge = new File(['x'], 'huge-video-export.mov');
      Object.defineProperty(huge, 'size', { value: 3 * 1024 ** 3 });
      dt.items.add(huge);
      // DataTransfer copies files, so hand over the patched object directly.
      const ev = new Event('drop', { bubbles: true, cancelable: true });
      Object.defineProperty(ev, 'dataTransfer', { value: { files: [huge], items: [] } });
      document.getElementById('dropzone').dispatchEvent(ev);
    });
    await expect(page.locator('#results .alert.alert--error')).toContainText('safe limit');
    await expect(page.locator('#create')).toBeDisabled();
    await page.getByRole('button', { name: 'Remove huge-video-export.mov' }).click();
    await expect(page.locator('#results .alert--error')).toHaveCount(0);
  });

  test('works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await expect(page.locator('#pick-files')).toBeInViewport();
    await expect(page.locator('#pick-folder')).toBeInViewport();
    await drop(page, payload([...THREE, { rel: 'notes/build-notes.txt', type: 'text/plain', name: 'a-very-long-file-name-for-the-solar-oven-final-report-draft-v3.txt' }]));
    await expect(page.locator('#file-list .zip-item')).toHaveCount(4);
    const { download } = await createAndDownload(page);
    expect(download.suggestedFilename()).toBe('archive.zip');
    await expect(page.locator('#download')).toBeInViewport();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win);
    for (const sel of ['#create', '#download', '#archive-name', '#level', '.zip-item__remove']) {
      const box = await page.locator(sel).first().boundingBox();
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width).toBeLessThanOrEqual(390);
    }
  });

  test('__demo shows a finished Solar Oven Report archive', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#file-list .zip-item')).toHaveCount(4);
    await expect(page.locator('#download')).toHaveText('Download archive.zip');
    await expect(page.locator('#stat-after')).not.toBeEmpty();
  });
});
